#include <iostream>
#include <string>
#include <sstream>

std::string markdownToHtml(const std::string& markdown) {
    // Convert the markdown text to HTML using Markdown
    std::string html = "";
    std::istringstream stream(markdown);
    std::string line;

    while (std::getline(stream, line)) {
        html += line;
    }

    return html;
}

int main() {
    std::string markdown = "# Hello World\nThis is a paragraph.\n*This* is a bold text.\n_This_ is an italic text.\n**This** is a bold and italic text.";
    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

